                        any_button = (uint8_t)(b != 0);
                        footer_text(&fa, &fb, &fc);
                        w = 4 + tw(&FONT_T, fa) + (fb ? FOOT_GAP + tw(&FONT_T, fb) : 0) + (fc ? FOOT_GAP + tw(&FONT_T, fc) : 0);
