                        ok = 0;
                    for (k = 0; k < n; k++)
                        if (tw(&FONT_XS, l[k]) > 224) {
                            if (ok)
                                printf("help card too wide: %s: \"%s\" (%d px)\n", btn_label(b), l[k], (int)tw(&FONT_XS, l[k]));
