/* SPDX-License-Identifier: GPL-3.0-only
 * User sample slots: adapted from Felucca's eng_sample.c, Copyright (C) 2026 Leo Kuroshita
 * (@kurogedelic), Hugelton Instruments. */
/* User sample slots (break loops), uploaded over USB with tools/upload_breaks.py
 * (or the break loops page): 2 slots, read in place through the XIP window. SMK-37 Pro: 80 KiB
 * then 120 KiB (see below). FM-1: 2 slots of 80 KiB at 0xA0000. Each slot has its own flash offset
 * and size. Slot = header (magic, count, name, data length, CRC32) + up to 16 zones + IMA ADPCM
 * data at +512. X0X plays zone 0 of a slot as a loop. */
typedef struct {
    uint32_t off, n, ls, le;     /* byte offset (from the slot data), samples, loop start / end */
    uint32_t rate;               /* source rate / 44100, Q16 */
    int16_t root16;
    int16_t pred;
    uint8_t idx, lo, hi, looped;
} smp_zone_t;
#if BOARD_SMK37 || defined(X0X_HOST)
/* SMK-37 Pro (fm1_flash_map.h; the host simulator, host/x0x_host.c, uses this map too). Slots 1 and 2 keep the flash offsets of the earlier layouts, so
 * their data stays valid: slot 1 0xC2000-0xD5FFF (80 KiB), slot 2 0xD6000-0xF3FFF (120 KiB), both in FL_SMP.
 * The 44 KiB window at 0xB0000-0xBAFFF (FL_SMPV) is not a sample slot. It is not added to these two:
 * protected BTIF / USRTRIM sits between that window and FL_SMP. */
#define SMP_USER_SLOTS 2
#define SMP_USER_OFF(k) ((k) == 0u ? 0xC2000u : 0xD6000u)
#define SMP_USER_SIZE(k) ((k) == 0u ? 0x14000u : 0x1E000u)
#define SMP_USER_MAX 0x1E000u                       /* the largest slot */
/* First 8 KiB of FL_SMPV: per-slot 4 KiB shadow of sector 0 so a mid-WRITE
 * cancel / failed END / power loss can put the last-good header+data back. */
#define SMP_SEC0_BACKUP 1
#define SMP_SEC0_BACKUP_OFF(k) (0xB0000u + (uint32_t)(k) * 0x1000u)
#ifdef FL_SMP_LO
_Static_assert(SMP_USER_SLOTS == 2u, "SMK: two user sample slots");
_Static_assert(SMP_USER_OFF(0u) == FL_SMP_LO && SMP_USER_OFF(0u) + SMP_USER_SIZE(0u) == SMP_USER_OFF(1u) &&
               SMP_USER_OFF(1u) + SMP_USER_SIZE(1u) == FL_SMP_HI, "SMK: slots 1 and 2 must fill FL_SMP");
_Static_assert(SMP_USER_OFF(0u) >= FL_SMPV_HI, "SMK: the sample slots must not use the VM spare");
_Static_assert(SMP_SEC0_BACKUP_OFF(0u) >= FL_SMPV_LO &&
               SMP_SEC0_BACKUP_OFF(SMP_USER_SLOTS - 1u) + 0x1000u <= FL_SMPV_HI,
               "SMK: sector-0 backup fits in FL_SMPV");
#endif
#else
/* FM-1: two slots of 80 KiB at 0xA0000 and 0xB4000. The old third slot at 0xC8000 is not offered,
 * and those bytes are not added to slot 2. */
#define SMP_USER_SLOTS 2
#define SMP_USER_OFF(k) (0xA0000u + (k) * 0x14000u)
#define SMP_USER_SIZE(k) ((void)(k), 0x14000u)
#define SMP_USER_MAX 0x14000u
#define SMP_SEC0_BACKUP 0
_Static_assert(SMP_USER_SLOTS == 2u, "FM-1: two user sample slots");
#endif
#define SMP_USER_DATA 512u
#define SMP_USER_MAGIC 0x504D5346u                  /* "FSMP" */
typedef struct {
    uint32_t magic;
    uint16_t version;
    uint8_t nz, rsv;
    char name[8];
    uint32_t data_len, crc, rsv2[2];
    smp_zone_t zone[16];
} smp_user_hdr_t;                                   /* 32 + 16 x 28 = 480 B, data at +512 */
static uint8_t usr_nz[SMP_USER_SLOTS];

#ifndef SMP_USER_XIP                                /* host: a RAM image of the slots */
#define SMP_USER_XIP(k) fm1_xip_ptr(SMP_USER_OFF(k))
#endif
static const uint8_t *smp_user_xip(uint32_t k) { return SMP_USER_XIP(k); }

#include "../crc32_nibble.h"
/* Same zlib CRC-32 as storage.c st_crc32 / SMP_END — keep scan fail-closed with END. */
#define smp_data_crc x0x_crc32

/* (re)read slot k: a valid header with sane zones and matching data CRC makes it usable.
 * Without the CRC check, a restored sector-0 header over wiped higher-sector data
 * (mid-rewrite abort past 0x1000) would still set usr_nz. */
static void smp_user_scan(uint32_t k)
{
    const smp_user_hdr_t *h = (const smp_user_hdr_t *)smp_user_xip(k);
    uint32_t i;
    usr_nz[k] = 0;
    if (h->magic != SMP_USER_MAGIC || h->version != 1 || !h->nz || h->nz > 16u ||
        h->data_len > SMP_USER_SIZE(k) - SMP_USER_DATA)
        return;
    for (i = 0; i < h->nz; i++) {
        const smp_zone_t *z = &h->zone[i];
        if (z->off > h->data_len || z->n > 2u * SMP_USER_SIZE(k) || z->off + (z->n + 1u) / 2u > h->data_len ||
            z->idx > 88u || !z->rate || z->rate > 4u << 16)
            return;
    }
    if (smp_data_crc(smp_user_xip(k) + SMP_USER_DATA, h->data_len) != h->crc)
        return;
    usr_nz[k] = h->nz;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* IMA ADPCM decoder step, shared by the BREAK player (breaks.c) and the 909 cymbals
 * (drum909.c). Format: 4 bit, mono, low nibble first, initial state predictor 0 /
 * index 0 (tools/sampleio.py ima_encode writes it).
 *
 * The tables and the decoder step are from Felucca's eng_sample.c
 * (Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hugelton Instruments, GPL-3.0).
 *
 * Tables are defined once in the TU that sets X0X_IMA_TABLES_DEFINE (drum909.c), and
 * declared extern elsewhere — same pattern as x0x_drum_tables.h. Host unit tests that
 * include a DSP file alone may define X0X_IMA_TABLES_DEFINE before the include. */
#pragma once
#include <stdint.h>

#ifdef X0X_IMA_TABLES_DEFINE
const int16_t IMA_STEP_T[89] = {
    7, 8, 9, 10, 11, 12, 13, 14, 16, 17, 19, 21, 23, 25, 28, 31, 34, 37, 41, 45, 50, 55, 60, 66, 73, 80, 88, 97,
    107, 118, 130, 143, 157, 173, 190, 209, 230, 253, 279, 307, 337, 371, 408, 449, 494, 544, 598, 658, 724, 796,
    876, 963, 1060, 1166, 1282, 1411, 1552, 1707, 1878, 2066, 2272, 2499, 2749, 3024, 3327, 3660, 4026, 4428,
    4871, 5358, 5894, 6484, 7132, 7845, 8630, 9493, 10442, 11487, 12635, 13899, 15289, 16818, 18500, 20350,
    22385, 24623, 27086, 29794, 32767};
const int8_t IMA_IDX_T[8] = {-1, -1, -1, -1, 2, 4, 6, 8};
#else
extern const int16_t IMA_STEP_T[89];
extern const int8_t IMA_IDX_T[8];
#endif

/* decode nibble i of d; updates the decoder state and returns the new sample */
static inline int32_t ima_decode(const uint8_t *d, uint32_t i, int32_t *pred, int32_t *idx)
{
    uint32_t byte = d[i >> 1], code = (i & 1u) ? (byte >> 4) : (byte & 15u);
    int32_t step = IMA_STEP_T[*idx], vd = step >> 3, p, x;
    if (code & 4u)
        vd += step;
    if (code & 2u)
        vd += step >> 1;
    if (code & 1u)
        vd += step >> 2;
    p = *pred + ((code & 8u) ? -vd : vd);
    *pred = p < -32768 ? -32768 : p > 32767 ? 32767 : p;
    x = *idx + IMA_IDX_T[code & 7u];
    *idx = x < 0 ? 0 : x > 88 ? 88 : x;
    return *pred;
}

#!/usr/bin/env python3
"""Exercise production SMC link publication across a TIMER5 interruption.

The real edge notifier, link producer, queue producer, project reset and poller
are compiled together. UI/platform calls schedule an interrupt after the poller
has sampled the link. MIDI actions are recorded at the dispatch boundary.
SMC_SOURCE selects the unchanged source for the negative control.
"""
import os
from pathlib import Path
import re
import shlex
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SOURCE = Path(os.environ.get("SMC_SOURCE", ROOT / "firmware/src/app/smc_mixer.c"))
source = SOURCE.read_text()
transport = (ROOT / "firmware/src/ble.c").read_text()


def function(text, name):
    match = re.search(r"^[^\n]*\b" + name + r"\([^\n]*\)\s*\{", text, re.M)
    if not match:
        raise RuntimeError(f"Production function not found: {name}")
    depth = 1
    end = match.end()
    while depth:
        if end == len(text):
            raise RuntimeError(f"Unterminated production function: {name}")
        depth += (text[end] == "{") - (text[end] == "}")
        end += 1
    return text[match.start():end]


prefix = source[source.index("#define SMC_Q"):source.index("int smc_project_active")]
has_generation = "smc_link_published" in prefix
harness = r'''
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "app/smc_protocol.h"
#include "smc_fx_harness_stubs.h"
#define X0X_COLD
#define PROJ_BT_SMC_CENTRAL 16u
#define PROJ_BT_SMC_USER 32u
typedef struct { uint8_t kind, a, b, c; } pref_t;
enum { O_NONE, O_ASK, NKIT = 2 };
static struct { struct { uint8_t bt; } set; } proj;
static struct { uint8_t overlay, help; } ui;
static int locked, interrupt_at, interrupt_up;
static unsigned dispatched, notices, solo;
static uint8_t observed[3][3];
static int perf_testing(void);
static int ui_project_busy(void);
static void engine_smc_solo(int n) { solo = (unsigned)n; }
static void engine_smc_solo_targets(uint8_t p,uint16_t a,uint16_t b) { (void)a; (void)b; engine_smc_solo(p); }
static void ui_say(const char *a, const char *b) { (void)a; (void)b; notices++; }
#define smc_ui_cancel() ((void)0) /* Presentation is exercised by smc_ui_test.c. */
''' + prefix + "\n" + "\n".join(function(source, name) for name in
    (name for name in ("smc_solo_union", "smc_peer_drop", "smc_ble_midi_slot", "smc_ble_link_slot", "smc_project_active", "smc_solo_clear") if re.search(r"\b" + name + r"\(", source))) + "\n" + "\n".join(function(source, name) for name in (
    "smc_project_drop", "smc_project_reset", "smc_ble_midi", "smc_ble_link")) + r'''
static uint8_t ble_central_link_seen[2];
''' + function(transport, "ble_central_link_notify_slot") + r'''

static void interrupt(int site)
{
    if (interrupt_at != site) return;
    interrupt_at = 0;
    ble_central_link_notify_slot(0, interrupt_up);
}
static int perf_testing(void) { interrupt(1); return 0; }
static int ui_project_busy(void) { interrupt(2); return locked; }
static uint8_t smc_message(const uint8_t *m, uint8_t n, int allow)
{
    if (!allow || n != 3 || dispatched >= 3) abort();
    memcpy(observed[dispatched++], m, 3);
    return 0;
}
static void smc_guarded_button(uint8_t n, int mmc, int allow)
{ (void)n; (void)mmc; (void)allow; abort(); }
''' + function(source, "smc_mmc_drain_stop") + "\n" + ((function(source, "smc_poll_peer") + "\n") if "smc_poll_peer" in source else "") + function(source, "smc_poll") + r'''

static int check_input(int up)
{
    static const uint8_t controls[3][3] = {
        {0xE0, 0, 100}, {0xB0, 16, 1}, {0x90, 0x18, 127}
    };
    /* The transport already reported this state. It does not retransmit it. */
    ble_central_link_notify_slot(0, up);
    for (unsigned i = 0; i < 3; i++) smc_ble_midi(controls[i], 3);
    smc_poll();
    if (smc.up != up || dispatched != (up ? 3u : 0u) ||
        (up && memcmp(controls, observed, sizeof controls)) ||
        (!up && (smc_rx_diag() >> 24) != 2u)) {
        fprintf(stderr, "FAIL: transport=%d application=%u dispatched=%u reason=%u\n",
                up, smc.up, dispatched, (unsigned)(smc_rx_diag() >> 24));
        return 1;
    }
    return 0;
}

int main(int argc, char **argv)
{
    if (argc != 3) return 2;
    int mode = atoi(argv[1]), site = atoi(argv[2]);
    proj.set.bt = PROJ_BT_SMC_CENTRAL;
    if (mode <= 1) {
        /* A newer reconnect/disconnect arrives after the old state was read. */
        int up = mode == 0;
        ble_central_link_notify_slot(0, up); smc_poll();
        ble_central_link_notify_slot(0, !up);
        interrupt_at = site; interrupt_up = up;
        smc_poll(); smc_poll();
        if (interrupt_at) return 3;
        return check_input(up);
    }
    ble_central_link_notify_slot(0, 1); smc_poll();
    smc.picked = 0x55; smc.seen = 0xAA; smc.known[5] = 1;
    if (mode == 2) {
        /* Unchanged connection must not reset pickup or republish notices. */
        unsigned before = notices;
        for (unsigned i = 0; i < 32; i++) smc_poll();
        if (notices != before || smc.picked != 0x55 || smc.seen != 0xAA ||
            !smc.known[5]) return 4;
    } else if (mode == 3) {
        /* Coalesced down/up remains a new link even if the final state is up. */
        ble_central_link_notify_slot(0, 0); ble_central_link_notify_slot(0, 1); smc_poll();
        if (smc.picked || smc.seen || smc.known[5]) return 5;
    } else if (mode == 4) {
        /* A project lock/reset must leave a newer link publication available. */
        locked = 1;
        ble_central_link_notify_slot(0, 0); smc_poll(); smc_project_reset();
        ble_central_link_notify_slot(0, 1); smc_poll();
        locked = 0; smc_poll();
    } else if (mode == 5) {
        smc.solo = 1; solo = 1;
        ble_central_link_notify_slot(0, 0); smc_poll();
        if (smc.solo || solo || smc.picked || smc.seen) return 6;
        return check_input(0);
    } else if (mode == 6) {
#ifdef LINK_GENERATION
        /* Zero is a valid disconnected publication after unsigned wrap. */
        smc_link_published = smc_link_seen = UINT32_MAX;
        ble_central_link_notify_slot(0, 0); smc_poll();
        if (smc_link_published != 0 || smc.up) return 7;
        ble_central_link_notify_slot(0, 1); smc_poll();
#else
        return 77;
#endif
    } else if (mode == 7) {
#ifdef LINK_GENERATION
        ble_central_link_notify_slot(0, 0); smc_poll();
        smc_link_published = smc_link_seen = UINT32_MAX - 1u;
        ble_central_link_notify_slot(0, 1); smc_poll();
        if (smc_link_published != 1u || !smc.up) return 8;
#else
        return 77;
#endif
    } else return 2;
    return check_input(1);
}
'''

cases = [("reconnect", 0, 1), ("reconnect-late", 0, 2),
         ("disconnect", 1, 1), ("disconnect-late", 1, 2),
         ("stable-pickup", 2, 0), ("coalesced-edges", 3, 0),
         ("project-reset", 4, 0), ("disconnect-clears-solo", 5, 0)]
if has_generation:
    cases += [("wrap-down", 6, 0), ("wrap-up", 7, 0)]

with tempfile.TemporaryDirectory(prefix="smc-link-") as tmp:
    c = Path(tmp) / "test.c"
    executable = Path(tmp) / "test"
    c.write_text(harness)
    flags = shlex.split(os.environ.get("SAN_FLAGS", ""))
    if has_generation:
        flags.append("-DLINK_GENERATION")
    subprocess.run([os.environ.get("CC", "cc"), "-std=c99", "-O2", "-g",
                    "-Wall", "-Wextra", "-Werror", *flags,
                    "-I" + str(ROOT / "firmware/src"),
                    "-I" + str(ROOT / "tests/host"),
                    str(c), "-o", str(executable)], check=True)
    failures = []
    for label, mode, site in cases:
        result = subprocess.run([str(executable), str(mode), str(site)], check=False)
        print(f'{"PASS" if result.returncode == 0 else "FAIL"} {label}', flush=True)
        if result.returncode:
            failures.append((label, result.returncode))
    if failures:
        raise SystemExit(f"FAIL: {len(failures)}/{len(cases)} SMC link cases: {failures}")
print(f"PASS: {len(cases)} SMC link cases preserve reconnect, disconnect, pickup, reset and wrap")
